#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.20.0  -  the new edit screen
#
#   * Editing a clip looks and works like a video editor:
#       - round close button, title, white round arrow to finish
#       - the clip in the middle, play / pause, "0:03 / 0:17", undo and redo
#       - a timeline with the white playhead in the middle: drag sideways to
#         move through the clip, pinch to zoom, time marks on top
#       - tracks: the clip (with its pictures), the song, the voiceover, and
#         one track for every text, sticker and caption
#       - tap the clip to trim it with the white handles; tap a text track and
#         drag its ends to choose when it shows
#       - "+ Add audio" and "+ Add text" right on the timeline
#       - tools at the bottom: Audio, Text, Voice, Captions, Stickers,
#         Filters, Adjust, Speed, Rotate, Volume
#   * Captions: type a line, it appears low on the clip for 3 seconds from
#     the playhead (drag its track to change that).
#   * Undo / redo for every change (photos too).
#   * Photos get the same top bar, buttons and undo / redo.
#   * Also included: the chat code tidy-up for newer Flutter, and the delete
#     tool that retries when the internet drops.
#
# Run from the project root:   bash update_v1200_edit_screen.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="fd5c22e296e5f150bcc3d63dadcac033577475cab10a4eb192efac2ab214de2c"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/models/vanish.dart ] || { echo "ERROR: v1.19.6 is not installed. Run update_v1196_sound_chats.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
# Some browsers save this file with Windows line endings (CRLF). Those
# extra characters corrupt the payload, so strip any control character
# sitting at the end of a line before decoding.
awk '/^__PAYLOAD__/{f=1;next} /^#/{f=0} f' "$0" | sed 's/[[:cntrl:]]*$//' | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       expected  $EXPECTED_SHA256"
  echo "       actual    $ACTUAL"
  echo "       your file is $(wc -c < "$0") bytes; it should be 568585 bytes."
  echo "       Smaller size = the download was cut short: download it again."
  echo "       Same size but still failing, run:"
  echo "         sed -i 's/[[:cntrl:]]*$//' $(basename "$0") && bash $(basename "$0")"
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh tools/delete_user.sh 2>/dev/null || true
# keys for the delete tool live in ~/.instantgram-admin, never in the project
touch .gitignore
for p in '*firebase-adminsdk*.json' '__pycache__/'; do
  grep -qxF "$p" .gitignore || echo "$p" >> .gitignore
done
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.20.0 is in place."
echo ""
echo "Nothing to set up. Build a new APK to get the new edit screen."
exit 0

